package com.example.aymobiledigitallibrary.ui.screens
import androidx.compose.foundation.layout.*;import androidx.compose.material3.*;import androidx.compose.runtime.*;import androidx.compose.ui.Modifier;import androidx.compose.ui.unit.dp;import com.example.aymobiledigitallibrary.model.ParticipantInfo;import com.example.aymobiledigitallibrary.ui.components.*
@Composable fun SessionSetupScreen(initialId:String,onContinue:(ParticipantInfo)->Unit){var age by remember{ mutableStateOf("")}; var gender by remember{ mutableStateOf("")}; var s1 by remember{ mutableIntStateOf(0)}; var s2 by remember{ mutableIntStateOf(0)}; var s3 by remember{ mutableIntStateOf(0)}; var s4 by remember{ mutableIntStateOf(0)}; var s5 by remember{ mutableIntStateOf(0)}; val ok=age.isNotBlank()&&gender.isNotBlank()&&listOf(s1,s2,s3,s4,s5).all{it in 1..5};ScreenContainer{SectionTitle("Session Setup");Text("This ID is automatically generated and does not contain your personal identity.");Text(initialId);OutlinedTextField(age,{age=it},label={Text("Age")},modifier=Modifier.fillMaxWidth());Row{listOf("Female","Male","Other").forEach{FilterChip(selected=gender==it,onClick={gender=it},label={Text(it)},modifier=Modifier.padding(end=8.dp))}};LikertScale(s1,{s1=it},"Not at all","Extremely");LikertScale(s2,{s2=it},"Not at all","Extremely");LikertScale(s3,{s3=it},"Rarely","Daily");LikertScale(s4,{s4=it},"Rarely","Daily");LikertScale(s5,{s5=it},"Poor","Excellent");PrimaryButton("Continue"){onContinue(ParticipantInfo(initialId,age,gender,s1,s2,s3,s4,s5))}}}
